static Bounds B(GameObject g){var rr=g.GetComponentsInChildren<Renderer>();var b=new Bounds(g.transform.position,Vector3.zero);if(rr.Length>0){b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);}return b;}
static GameObject Copy(GameObject src,Transform parent,Vector3 at,float width,string name){var g=UnityEngine.Object.Instantiate(src,parent);g.name=name;g.SetActive(true);g.transform.position=at;var b=B(g);g.transform.localScale*=width/Mathf.Max(.01f,b.size.x);b=B(g);g.transform.position+=new Vector3(at.x-b.center.x,at.y-b.min.y,at.z-b.center.z);return g;}
static void Run(){if(!File.Exists(W+"/work/run.flag"))return;File.Delete(W+"/work/run.flag");try{var s=SceneManager.GetSceneByPath("Assets/Bundles/Scenes/10005a.unity");if(!s.IsValid()||!s.isLoaded)s=EditorSceneManager.OpenScene("Assets/Bundles/Scenes/10005a.unity",OpenSceneMode.Additive);EditorSceneManager.SaveScene(s,W+"/outputs/10005a_before.unity",true);var reference=EditorSceneManager.OpenScene("Assets/Bundles/Scenes/10001.unity",OpenSceneMode.Additive);var ts=All(reference);var rock=ts.First(t=>t.name.StartsWith("SGS_Cliff")&&t.GetComponentsInChildren<Renderer>().Length>0).gameObject;var grass=ts.First(t=>t.name.StartsWith("GrassPatchDemo")&&t.GetComponent<Renderer>()).gameObject;var old=All(s);var root=new GameObject("10005a_Natural_Stone_And_Grass_Polish");SceneManager.MoveGameObjectToScene(root,s);var terrain=old.Select(t=>t.GetComponent<Terrain>()).First(t=>t);int count=0;foreach(var t in old.Where(t=>t.name=="Cave_R09_WallSegment"&&t.gameObject.activeInHierarchy)){var b=B(t.gameObject);Copy(rock,root.transform,new Vector3(b.center.x,b.min.y,b.center.z),b.size.x,"Reference10001_Cliff_"+count++);t.gameObject.SetActive(false);}foreach(var t in old.Where(t=>t.gameObject.activeInHierarchy&&(t.name.StartsWith("Forest_Canopy_Tree_")||t.name=="Rock_1"||t.name=="Cave_R09_WallSegment"))){for(int i=0;i<3;i++){var p=t.position+new Vector3(Mathf.Cos(i*2.1f)*.85f,0,Mathf.Sin(i*2.1f)*.85f);p.y=terrain.SampleHeight(p)+terrain.transform.position.y+.015f;var g=Copy(grass,root.transform,p,1.5f,"Reference10001_Grass_"+count++);g.transform.Rotate(0,i*117,0);foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);}}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);EditorSceneManager.CloseScene(reference,true);File.WriteAllText(W+"/outputs/result.txt","Cliff and grass instances: "+count+". Saved only 10005a scene.");}catch(Exception e){File.WriteAllText(W+"/work/error.txt",e.ToString());}}
